from manim import *
class CW_KochCurve(Scene):
    def construct(self):
        def KochCurve(
            n, length=12, stroke_width=8, color=("
        ):
            l = length / (3 ** n)
            LineGroup = Line().set_length(l)
            def NextLevel(LineGroup):
                return VGroup(
                    *[LineGroup.copy().rotate(i) for i in [0, PI / 3, -PI / 3, 0]]
                ).arrange(RIGHT, buff=0, aligned_edge=DOWN)
            for _ in range(n):
                LineGroup = NextLevel(LineGroup)
            KC = (
                VMobject(stroke_width=stroke_width)
                .set_points(LineGroup.get_all_points())
                .set_color(color)
            )
            return KC
        level = Variable(0, Tex("level"), var_type=Integer).set_color("
        txt = (
            VGroup(Tex("Koch Curve", font_size=60), level)
            .arrange(DOWN, aligned_edge=LEFT)
            .to_corner(UL)
        )
        kc = KochCurve(0, stroke_width=12).to_edge(DOWN, buff=2.5)
        self.add(txt, kc)
        self.wait()
        for i in range(1, 6):
            self.play(
                level.tracker.animate.set_value(i),
                kc.animate.become(
                    KochCurve(i, stroke_width=12 - (2 * i)).to_edge(DOWN, buff=2.5)
                ),
            )
            self.wait()
        for i in range(4, -1, -1):
            self.play(
                level.tracker.animate.set_value(i),
                kc.animate.become(
                    KochCurve(i, stroke_width=12 - (2 * i)).to_edge(DOWN, buff=2.5)
                ),
            )
            self.wait()

from manim import *
class SquareFunction(Scene):
    def construct(self):
        axes = Axes(
            x_range = [-5, 5.1, 1],
            y_range = [-1.5, 1.5, 1],
            x_length = 2 * TAU,
            axis_config = {"color": GREEN},
            tips = False,
            )
        def squareWave(x):
            if int(x)%2 == 0:
                return 1 * x // abs(x)
            else:
                return -1 * x // abs(x)
        def Sinn(x, n):
            result = 0
            for i in range(1, n + 1, 2):
                result += (2 / (i * np.pi)) * (2) * np.sin(i * x * np.pi)
            return result
        def SINN(x, i):
            return (2 / (i * np.pi)) * (2) * np.sin(i * x * np.pi)
        square_graph = axes.plot(squareWave, x_range = (-4.9, 4.9, 0.01), **{"discontinuities": [x for x in range(-5, 6)]})
        values = [0]
        values1 = [0]
        index = 1
        for i in range(1, 31, 2):
            values.append(axes.plot(lambda x: SINN(x, i), x_range = (-4.9, 4.9, 0.1)))
            values1.append(axes.plot(lambda x: Sinn(x, i), x_range = (-4.9, 4.9, 0.1), color = BLUE))
        self.add(axes, square_graph,  values[1])
        self.play(ReplacementTransform(values[1], values1[1]))
        for i in range(2, 15):
            self.play(Create(values[i]))
            self.wait(1)
            self.play(ReplacementTransform(values[i], values1[i]), ReplacementTransform(values1[i-1], values1[i]))

