import numpy as np
class GradientDeltoid(Scene):
    def construct(self):
        curves = VGroup()
        colors = [RED, ORANGE, YELLOW, GREEN, BLUE, PURPLE]
        for i, color in enumerate(colors):
            def deltoid(t, offset=i*0.1):
                x = 2 * np.cos(t + offset) + np.cos(2*(t + offset))
                y = 2 * np.sin(t + offset) - np.sin(2*(t + offset))
                return np.array([x, y, 0])
            curve = ParametricFunction(
                deltoid,
                t_range=[0, 2*PI],
                color=color,
                stroke_width=4
            ).scale(0.7)
            curves.add(curve)
        self.play(LaggedStartMap(Create, curves, lag_ratio=0.1), run_time=4)
        self.wait(2)

